Here is the implementation of the `jsonToArray` function in JavaScript:

```javascript
function jsonToArray(json) {
  function processValue(value) {
    if (Array.isArray(value)) {
      return value.map(processValue);
    } else if (typeof value === 'object' && value !== null) {
      return Object.entries(value).map(([key, val]) => [key, processValue(val)]);
    } else if (typeof value === 'string') {
      if (/^Date\(".+"\)$/.test(value)) {
        return new Date(value.slice(6, -2));
      } else if (/^RegExp\(".+", ".+"\)$/.test(value)) {
        const [, pattern, flags] = value.match(/^RegExp\("(.+)", "(.+)"\)$/);
        return new RegExp(pattern, flags);
      } else if (/^Function\(".*"\)$/.test(value)) {
        const [, functionBody] = value.match(/^Function\("(.+)"\)$/);
        return new Function(`return ${functionBody}`)();
      }
    }
    return value;
  }

  const obj = JSON.parse(json);
  const result = [];

  for (const key in obj) {
    const value = obj[key];
    result.push([key, processValue(value)]);
  }

  return result;
}
```

