  // Helper function to check if a number is prime
  function isPrime(num) {
    if (num <= 1) {
      return false;
    }
    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) {
        return false;
      }
    }
    return true;
  }

  // Find the first k prime numbers in the array
  const primes = [];
  for (let num of arr) {
    if (isPrime(num)) {
      primes.push(num);
      if (primes.length === k) {
        return primes;
      }
    }
  }

  // Return -1 or an empty array if no prime number is found
  if (k <= 0) {
    return [];
  } else if (primes.length === 0) {
    return -1;
  } else {
    return primes;
  }
}
